import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";
import type { Locator } from "@playwright/test";
import { randomUUID } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";

async function paint(control: Locator) {
  return control.evaluate((element) => {
    const s = getComputedStyle(element);
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1;
    const ctx = canvas.getContext("2d")!;
    const rgba = (color: string) => {
      ctx.clearRect(0, 0, 1, 1);
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 1, 1);
      return Array.from(ctx.getImageData(0, 0, 1, 1).data);
    };
    const over = (fg: number[], bg: number[]) =>
      fg
        .slice(0, 3)
        .map((v, i) => (v * fg[3]) / 255 + bg[i] * (1 - fg[3] / 255))
        .concat(255);
    const luminance = (color: number[]) =>
      color
        .slice(0, 3)
        .map((v) => v / 255)
        .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4))
        .reduce((sum, v, i) => sum + v * [0.2126, 0.7152, 0.0722][i], 0);
    const ratio = (a: number[], b: number[]) => {
      const x = luminance(a),
        y = luminance(b);
      return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
    };
    const parents = [];
    for (
      let parent = element.parentElement;
      parent;
      parent = parent.parentElement
    )
      parents.unshift(parent);
    let exterior = [255, 255, 255, 255];
    for (const parent of parents)
      exterior = over(rgba(getComputedStyle(parent).backgroundColor), exterior);
    const fill = over(rgba(s.backgroundColor), exterior);
    return {
      textContrast:
        s.backgroundImage === "none"
          ? ratio(over(rgba(s.color), fill), fill)
          : null,
      boundaryContrast: ratio(over(rgba(s.borderTopColor), exterior), exterior),
      focusContrast: ratio(over(rgba(s.outlineColor), exterior), exterior),
      background: s.background,
      border: s.borderColor,
      shadow: s.boxShadow,
      filter: s.filter,
      translate: s.translate,
      transition: s.transition,
      decoration: s.textDecorationLine,
      outline: s.outlineStyle,
      width: element.getBoundingClientRect().width,
      height: element.getBoundingClientRect().height,
    };
  });
}

for (const appearance of ["purple", "vercel"]) {
  for (const mode of ["light", "dark"]) {
    test(`button hover: ${appearance} ${mode}`, async ({
      page,
      themeUser,
      themeDatabase,
    }, info) => {
      const before = process.env.BUTTON_CAPTURE_BEFORE === "1";
      const directory = `/tmp/mailloop-buttons-${before ? "before" : "after"}/${info.project.name}-${appearance}-${mode}`;
      await mkdir(directory, { recursive: true });
      await page.addInitScript(
        ({ appearance, mode }) => {
          localStorage.setItem("mailloop-appearance", appearance);
          localStorage.setItem("mailloop-theme", mode);
        },
        { appearance, mode },
      );
      await setThemePlan(themeUser, "FREE");
      await setThemeQuotaGating(true);
      await page.goto("/usage");
      const compare = page.getByRole("link", {
        name: "Compare plans",
        exact: true,
      });
      const premium = page
        .getByRole("button", { name: "Upgrade to Premium", exact: true })
        .first();
      await expect(compare).toBeVisible();
      await compare.scrollIntoViewIfNeeded();
      await page.evaluate(() => document.fonts.ready);
      const resting = await paint(compare);
      await page.screenshot({ path: `${directory}/rest.png` });
      const premiumRest = await paint(premium);
      const touch = info.project.name === "mobile";
      if (!touch) {
        await compare.hover();
        await page.waitForTimeout(250);
        const hovered = await paint(compare);
        await page.screenshot({ path: `${directory}/hover.png` });
        if (!before) {
          expect(hovered.decoration).toBe("none");
          expect(hovered.background).not.toBe(resting.background);
          expect(hovered.border).not.toBe(resting.border);
          expect(hovered.shadow).not.toBe("none");
          expect(hovered.transition).toContain("0.18s");
          expect([hovered.width, hovered.height]).toEqual([
            resting.width,
            resting.height,
          ]);
        }
        await page.mouse.down();
        await page.waitForTimeout(220);
        await page.screenshot({ path: `${directory}/pressed.png` });
        await page.mouse.move(0, 0);
        await page.mouse.up();
        await expect(compare).toBeVisible();
      }
      await compare.focus();
      await page.keyboard.press("Tab");
      await page.keyboard.press("Shift+Tab");
      await expect(compare).toBeFocused();
      await expect(compare).toHaveCSS("outline-style", "solid");
      await page.screenshot({ path: `${directory}/focus.png` });
      await premium.scrollIntoViewIfNeeded();
      if (!touch) await premium.hover({ force: true });
      await page.waitForTimeout(250);
      const premiumHover = await paint(premium);
      await writeFile(
        `${directory}/premium.json`,
        JSON.stringify(
          { resting: premiumRest, hovered: premiumHover },
          null,
          2,
        ),
      );
      await page.emulateMedia({ reducedMotion: "reduce" });
      if (!before) await expect(compare).toHaveCSS("transition-duration", "0s");
      await page.screenshot({ path: `${directory}/reduced.png` });
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      if (!before) {
        await page.emulateMedia({ reducedMotion: "no-preference" });
        for (const state of ["aria-busy", "aria-disabled"]) {
          await compare.evaluate(
            (element, state) => element.setAttribute(state, "true"),
            state,
          );
          await compare.hover({ force: true });
          await expect(compare).toHaveCSS("transition-duration", "0s");
          await expect(compare).toHaveCSS("translate", "none");
          await expect(compare).toHaveCSS("filter", "none");
          await compare.evaluate(
            (element, state) => element.removeAttribute(state),
            state,
          );
        }
        // Black themes require Premium. Compare plans is a Free-plan control;
        // exercise the paid appearances on shared settings/contacts controls.
        await setThemePlan(themeUser, "PAID");
        await page.goto("/settings");
        await expect(page.locator("html")).toHaveAttribute(
          "data-appearance",
          appearance,
        );
        await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
        const download = page.getByRole("link", { name: "Download my data" });
        await download.scrollIntoViewIfNeeded();
        const downloadRest = await paint(download);
        if (appearance === "vercel")
          expect(downloadRest.boundaryContrast).toBeGreaterThanOrEqual(3);
        await download.hover();
        await page.waitForTimeout(220);
        if (!touch) {
          expect((await paint(download)).background).not.toBe(
            downloadRest.background,
          );
          await expect(download).toHaveCSS("text-decoration-line", "none");
        }
        await page.screenshot({ path: `${directory}/settings.png` });
        const privacy = page.getByRole("link", {
          name: "Privacy Policy",
          exact: true,
        });
        await privacy.hover();
        await expect(privacy).toHaveCSS("text-decoration-line", "underline");
        await themeDatabase.query(
          'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
          [randomUUID(), themeUser, "Hover fixture", "[REDACTED_EMAIL]"],
        );
        await page.goto("/contacts");
        const ghost = page
          .getByRole("button", { name: "Delete", exact: true })
          .first();
        await ghost.scrollIntoViewIfNeeded();
        const ghostRest = await paint(ghost);
        await ghost.hover();
        await page.waitForTimeout(220);
        const ghostHover = await paint(ghost);
        if (!touch)
          expect(ghostHover.background).not.toBe(ghostRest.background);
        expect(ghostHover.shadow).toBe("none");
        expect(ghostHover.translate).toMatch(/none|0px/);
        await page.screenshot({ path: `${directory}/ghost.png` });
        await ghost.evaluate(
          (el) =>
            new Promise<void>((resolve) => {
              const ready = () =>
                Object.keys(el).some((key) => key.startsWith("__reactProps"))
                  ? resolve()
                  : requestAnimationFrame(ready);
              ready();
            }),
        );
        await ghost.click();
        const cancel = page.getByRole("button", {
          name: "Cancel",
          exact: true,
        });
        await expect(cancel).toBeVisible();
        await page.mouse.move(0, 0);
        const cancelRest = await paint(cancel);
        if (appearance === "vercel")
          expect(cancelRest.boundaryContrast).toBeGreaterThanOrEqual(3);
        await cancel.hover();
        await page.waitForTimeout(220);
        const cancelHover = await paint(cancel);
        if (!touch) {
          expect(cancelHover.background).not.toBe(cancelRest.background);
          expect(cancelHover.border).not.toBe(cancelRest.border);
          expect(cancelHover.shadow).not.toBe("none");
          expect(cancelHover.transition).toContain("0.18s");
        } else {
          expect(cancelHover.background).toBe(cancelRest.background);
        }
        await page.screenshot({ path: `${directory}/outline.png` });
        await page.emulateMedia({ reducedMotion: "reduce" });
        await expect(cancel).toHaveCSS("transition-duration", "0s");
        await cancel.click();
        await page.emulateMedia({ reducedMotion: "no-preference" });
        await ghost.evaluate(
          (element) => ((element as HTMLButtonElement).disabled = true),
        );
        await ghost.hover({ force: true });
        await expect(ghost).toHaveCSS("transition-duration", "0s");
        await expect(ghost).toHaveCSS("translate", "none");
        await expect(ghost).toHaveCSS("filter", "none");
        await page.goto("/pricing");
        const current = page
          .getByRole("button", { name: "Current plan", exact: true })
          .first();
        await expect(current).toBeDisabled();
        await expect(current).toHaveCSS("transition-duration", "0s");
      }
    });
  }
}

for (const appearance of ["purple", "vercel"]) {
  for (const mode of ["light", "dark"]) {
    test(`paid primary and destructive feedback: ${appearance} ${mode}`, async ({
      page,
      themeUser,
      themeDatabase,
    }, info) => {
      const before = process.env.BUTTON_CAPTURE_BEFORE === "1";
      const directory = `/tmp/mailloop-neutral-buttons-${before ? "before" : "after"}/${info.project.name}-${appearance}-${mode}`;
      await mkdir(directory, { recursive: true });
      await setThemePlan(themeUser, "PAID");
      await setThemeQuotaGating(true);
      await page.addInitScript(
        ({ appearance, mode }) => {
          localStorage.setItem("mailloop-appearance", appearance);
          localStorage.setItem("mailloop-theme", mode);
        },
        { appearance, mode },
      );
      const touch = info.project.name === "mobile";
      async function check(control: Locator, name: string) {
        await page.waitForLoadState("networkidle");
        await control.scrollIntoViewIfNeeded();
        await page.mouse.move(0, 0);
        await page.waitForTimeout(220);
        await control.evaluate((el) =>
          el.addEventListener(
            "click",
            (event) => {
              event.preventDefault();
              event.stopImmediatePropagation();
            },
            { capture: true },
          ),
        );
        const rest = await paint(control);
        const bounds = await control.boundingBox();
        await page.screenshot({ path: `${directory}/${name}-rest.png` });
        if (touch)
          await control.dispatchEvent("pointerover", { pointerType: "touch" });
        else await control.hover();
        await page.waitForTimeout(220);
        const hover = await paint(control);
        await page.screenshot({ path: `${directory}/${name}-hover.png` });
        if (!before && appearance === "vercel") {
          expect(rest.textContrast).toBeGreaterThanOrEqual(4.5);
          expect(hover.textContrast).toBeGreaterThanOrEqual(4.5);
          if (touch) {
            expect(hover.background).toBe(rest.background);
            const touchSession = await page.context().newCDPSession(page);
            try {
              await touchSession.send("Input.dispatchTouchEvent", {
                type: "touchStart",
                touchPoints: [
                  {
                    x: bounds!.x + bounds!.width / 2,
                    y: bounds!.y + bounds!.height / 2,
                  },
                ],
              });
              await page.waitForTimeout(220);
              const pressed = await paint(control);
              expect(pressed.textContrast).toBeGreaterThanOrEqual(4.5);
              expect(await control.boundingBox()).toEqual(bounds);
              await page.screenshot({
                path: `${directory}/${name}-touch-pressed.png`,
              });
            } finally {
              await touchSession.send("Input.dispatchTouchEvent", {
                type: "touchEnd",
                touchPoints: [],
              });
              await touchSession.detach();
            }
            await page.waitForTimeout(220);
            await expect
              .poll(async () => (await paint(control)).background)
              .toBe(rest.background);
            expect(await control.boundingBox()).toEqual(bounds);
          } else {
            expect(hover.background).not.toBe(rest.background);
            expect(hover.filter).toBe("none");
            expect(hover.transition).toContain("0.18s");
            expect(await control.boundingBox()).toEqual(bounds);
            await page.mouse.down();
            await page.waitForTimeout(220);
            const pressed = await paint(control);
            expect(pressed.background).not.toBe(hover.background);
            expect(pressed.textContrast).toBeGreaterThanOrEqual(4.5);
            expect(await control.boundingBox()).toEqual(bounds);
            await page.screenshot({ path: `${directory}/${name}-pressed.png` });
            await page.mouse.up();
          }
        }
        await control.focus();
        await page.keyboard.press("Tab");
        await page.keyboard.press("Shift+Tab");
        await expect(control).toBeFocused();
        await expect(control).toHaveCSS("outline-style", "solid");
        if (!before && appearance === "vercel")
          expect((await paint(control)).focusContrast).toBeGreaterThanOrEqual(
            3,
          );
        await page.screenshot({ path: `${directory}/${name}-focus.png` });
        await page.emulateMedia({ reducedMotion: "reduce" });
        if (!before)
          await expect(control).toHaveCSS("transition-duration", "0s");
        await page.emulateMedia({ reducedMotion: "no-preference" });
        if (!before && appearance === "vercel") {
          const states = ["aria-disabled", "aria-busy"];
          if (await control.evaluate((el) => el instanceof HTMLButtonElement))
            states.push("disabled");
          for (const state of states) {
            await control.evaluate(
              (el, state) =>
                el.setAttribute(state, state === "disabled" ? "" : "true"),
              state,
            );
            const disabled = await paint(control);
            await control.hover({ force: true });
            await expect(control).toHaveCSS("transition-duration", "0s");
            await expect(control).toHaveCSS("filter", "none");
            expect((await paint(control)).background).toBe(disabled.background);
            await control.evaluate(
              (el, state) => el.removeAttribute(state),
              state,
            );
          }
        }
      }
      await page.goto("/templates");
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
      // Module-backed primary link uses the same adapter as the native button.
      await check(page.locator(".primary-action").first(), "primary-link");
      await themeDatabase.query(
        'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
        [randomUUID(), themeUser, "Feedback fixture", "[REDACTED_EMAIL]"],
      );
      await page.goto("/contacts");
      const expand = page.getByRole("button", {
        name: "Expand contacts table",
        exact: true,
      });
      if (await expand.isVisible()) await check(expand, "icon");
      await check(
        page.getByRole("button", { name: "Save contact", exact: true }),
        "primary",
      );
      await page
        .getByRole("button", { name: "Delete", exact: true })
        .first()
        .click();
      const destructive = page
        .getByRole("dialog")
        .getByRole("button", { name: "Delete", exact: true });
      await check(destructive, "destructive");
    });
  }
}
